const FDC_HOME_SPELLS=[{"id":"maison-soins","name":"Soins","level":1,"abilities":"Emplacement de sort : niveau 1.\nEffet : 1D6 + Esprit.\nDistance : 30 m.\n1 cible / sort.","source":{"designId":"DAG-lZvA9NI","title":"Cartes de sorts","page":1,"revision":68}},{"id":"maison-soins-groupe","name":"Soins de groupe","level":2,"abilities":"Emplacement de sort : niveau 2.\nEffet : 1D4 + Esprit.\nSort de groupe.\nSort de zone : rayon de 15 m.","source":{"designId":"DAG-lZvA9NI","title":"Cartes de sorts","page":2,"revision":68}},{"id":"maison-boule-feu-mineur","name":"Boule de feu mineur","level":2,"abilities":"Emplacement de sort : niveau 2.\nEffet : 1D8 + Esprit.\nDistance : 25 m.\nSort de zone : rayon de 5 m.","source":{"designId":"DAG-lZvA9NI","title":"Cartes de sorts","page":3,"revision":68}},{"id":"maison-projectile-magique","name":"Projectile magique","level":0,"abilities":"Emplacement de sort : niveau 0.\nRéussite automatique.\nEffet : 1D6 + Esprit.\nDistance : 25 m.","source":{"designId":"DAG-lZvA9NI","title":"Cartes de sorts","page":4,"revision":68}},{"id":"maison-entrave-foret","name":"Entrave de la forêt","level":0,"abilities":"Emplacement de sort : niveau 0.\nTest de Force DD 15.\nEn cas d’échec, nouveau test à chaque tour.\nDistance : 15 m.\nSort de zone : rayon de 5 m.\nCoût : 1 utilisation par combat.","source":{"designId":"DAG-lZvA9NI","title":"Cartes de sorts","page":5,"revision":68}},{"id":"maison-prestidigitation","name":"Prestidigitation","level":0,"abilities":"Emplacement de sort : niveau 0.\nEffet : illusion mineure.\nUsage narratif / créatif.","source":{"designId":"DAG-lZvA9NI","title":"Cartes de sorts","page":6,"revision":68}}];
function fdcHomeSpellLibrary(){
 let entries=[];try{const saved=JSON.parse(localStorage.getItem('fdc-homebrew-spell-library-v1'));if(Array.isArray(saved))entries=saved;}catch(e){}
 for(const spell of FDC_HOME_SPELLS){if(!entries.some(x=>x.id===spell.id||String(x.name).toLocaleLowerCase('fr')===spell.name.toLocaleLowerCase('fr')))entries.push(structuredClone(spell));}
 try{localStorage.setItem('fdc-homebrew-spell-library-v1',JSON.stringify(entries));}catch(e){}
 return entries;
}

